<template><div class="page profile-page"><Header/><main><ProfileSidebar /><section class="profile-content"><div class="panel"><div class="heading"><h1>我的交易记录</h1><a>Download Transaction Report</a></div><div class="filters"><select v-model="type筛选"><option>全部 Types</option><option>Product Purchase</option><option>Design Fee</option></select><select v-model="status筛选"><option>全部 Status</option><option>Paid</option><option>已退款</option><option>Pending</option></select><input v-model="date筛选" placeholder="Start Date ~ End Date"><button @click="searchApplied=true">搜索</button><button class="light" @click="reset筛选s">重置</button></div><table><thead><tr><th>Date</th><th>Transaction ID</th><th>Type</th><th>Description</th><th>Amount</th><th>Status</th><th>Actions</th></tr></thead><tbody><tr v-if="filteredTransactions.length===0"><td colspan="7" class="empty"><div>♢</div><span>No data available</span></td></tr><tr v-for="t in filteredTransactions"><td>{{t.date}}</td><td>{{t.id}}</td><td>{{t.type}}</td><td>{{t.desc}}<small>{{t.ref}}</small></td><td>{{t.amount}}</td><td><span :class="['status',t.status.toLowerCase()]">{{t.status}}</span></td><td><a>Download</a></td></tr></tbody></table><div class="pagination">共50条　‹　<span>1</span>　2　3　4　5　…　20　›</div></div></section></main><Footer/></div></template>
<script setup lang="ts">import {computed,ref} from 'vue';import Header from '@/components/Header.vue';import Footer from '@/components/Footer.vue';import ProfileSidebar from '@/components/ProfileSidebar.vue';const type筛选=ref('全部 Types');const status筛选=ref('全部 Status');const date筛选=ref('');const searchApplied=ref(false);const transactions=[{date:'2026-02-03',id:'TXN-789123',type:'Product Purchase',desc:'Mid-Century Walnut Dining Table',ref:'Order # #ORD-456789',amount:'$500.00',status:'Paid'},{date:'2026-02-03',id:'TXN-456789',type:'Design Revision',desc:'Custom Bedroom Design Revision Fee',ref:'Design # #DSG-123456',amount:'$350.00',status:'已退款'},{date:'2026-02-02',id:'TXN-123456',type:'Product Purchase',desc:'Italian Style Living Room Design Package',ref:'Order # #ORD-123456',amount:'$350.00',status:'Pending'},{date:'2026-02-02',id:'TXN-321654',type:'Design Fee',desc:'Custom Bedroom Renovation Design Fee',ref:'Design ##DSG-123456',amount:'$200.00',status:'Paid'},{date:'2026-02-02',id:'TXN-654987',type:'Product Purchase',desc:'Modern Coffee Table',ref:'Order # #ORD-987321',amount:'$400.00',status:'Paid'},{date:'2026-02-01',id:'TXN-654907',type:'Product Purchase',desc:'Italian Style Living Room Design Package',ref:'Order # #ORD-123456',amount:'$2,599.00',status:'Paid'},{date:'2026-02-01',id:'TXN-654986',type:'Product Purchase',desc:'Custom Bedroom Renovation Design Fee',ref:'Design ##DSG-123456',amount:'$80.00',status:'Paid'},{date:'2026-02-01',id:'TXN-654989',type:'Product Purchase',desc:'Modern Coffee Table',ref:'Order # #ORD-987321',amount:'$2,000.00',status:'Paid'}];const filteredTransactions=computed(()=>transactions.filter(t=>(type筛选.value==='全部 Types'||t.type===type筛选.value)&&(status筛选.value==='全部 Status'||t.status===status筛选.value)&&(!date筛选.value||t.date.includes(date筛选.value))));function reset筛选s(){type筛选.value='全部 Types';status筛选.value='全部 Status';date筛选.value='';searchApplied.value=false}</script>
<style scoped>.page{background:#f4f4f5;color:#333;font:13px Arial;min-height:100vh}.page main{display:flex;width:100%;max-width:none;margin:0;background:#fff;min-height:740px}section{flex:1;background:#f4f4f5;padding:14px}.panel{background:#fff;padding:14px;border-radius:4px}.heading{display:flex;justify-content:space-between;align-items:center}.heading h1{margin:0 0 14px;font-size:22px}.heading a,td a{color:#0078b8}.filters{display:flex;gap:13px;margin-bottom:14px}.filters select,.filters input{height:38px;flex:1;border:1px solid #dfe3e8;padding:0 10px;background:#fff}.filters button{height:29px;padding:0 15px;border:1px solid #0878b0;background:#0878b0;color:#fff;border-radius:4px}.filters .light{background:#fff;color:#333;border-color:#333}table{width:100%;border-collapse:collapse}th{background:#f1f3f5;text-align:left;padding:11px 13px;font-weight:500}td{padding:11px 13px;border-bottom:1px solid #e2e5e8}td small{display:block;color:#999;margin-top:6px}.status{padding:4px 7px}.paid{color:#0a9b2f;background:#e6f9ea}.refunded{color:#e07800;background:#fff1df}.pending{color:#d69400;background:#fff8d9}.empty{height:150px;text-align:center;color:#777}.empty div{font-size:42px;color:#999;margin-top:15px}.empty span{display:block}.pagination{text-align:right;padding:16px}.pagination span{border:1px solid #0078b8;color:#0078b8;padding:7px}@media(max-width:800px){.page main{display:block}section{padding:8px}.filters{flex-wrap:wrap}table{font-size:11px;display:block;overflow:auto;white-space:nowrap}}
